// ConnectionLimit caps the number of open connections of a virtual server on a VIP. A new connection over the
// limit is dropped.
// Without source_address nor destination_address, all the connections share one count. With source_address, each
// client address has its own count. With destination_address, each destination address has its own count. With
// both, each address gets its own count on either side, and a connection is dropped when one of them is over.
// On a wildcard VIP (ip 0.0.0.0 or ::), the starling agent applies the limit on each address of the machine, each
// with its own count.
type ConnectionLimit struct {
	// Maximum number of connections allowed.
	// +required
	// +kubebuilder:validation:Minimum=0
	// +kubebuilder:validation:ExclusiveMinimum=true
	// +kubebuilder:validation:Maximum=9007199254740991
	MaxConnections int64 `json:"maxConnections"`

	// Count the connections per source address.
	// +optional
	SourceAddress *bool `json:"sourceAddress,omitempty"`

	// Count the connections per destination address.
	// +optional
	DestinationAddress *bool `json:"destinationAddress,omitempty"`
}

// ConnectionRateLimit caps the rate of a virtual server on a VIP with a token bucket. It counts new connections on
// TCP and every packet on UDP, and drops what is over the limit.
// Without source_address nor destination_address, all the traffic shares one bucket. With source_address or
// destination_address, each address has its own bucket. With both, each source and destination pair has its own
// bucket.
// On a wildcard VIP (ip 0.0.0.0 or ::), the starling agent applies the limit on each address of the machine, each
// with its own buckets.
type ConnectionRateLimit struct {
	// Maximum average rate, in connections (packets on UDP) per unit.
	// +required
	// +kubebuilder:validation:Minimum=0
	// +kubebuilder:validation:ExclusiveMinimum=true
	// +kubebuilder:validation:Maximum=9007199254740991
	Rate int64 `json:"rate"`

	// Size of the bucket, the number of connections (packets on UDP) let through at once above the rate. The bucket
	// refills at the rate.
	// +required
	// +kubebuilder:validation:Minimum=0
	// +kubebuilder:validation:ExclusiveMinimum=true
	// +kubebuilder:validation:Maximum=9007199254740991
	Burst int64 `json:"burst"`

	// Time unit of rate. UNKNOWN means SECOND.
	// +optional
	Unit TimeUnit `json:"unit,omitempty"`

	// Use one bucket per source address.
	// +optional
	SourceAddress *bool `json:"sourceAddress,omitempty"`

	// Use one bucket per destination address.
	// +optional
	DestinationAddress *bool `json:"destinationAddress,omitempty"`
}

// Extension point for limits dedicated to a load balancer implementation.
// valid extensions are:
// - flock.extensions.limit.starling_limit.v1.StarlingRateLimit
type LimitConfigTypedLimit struct {
	// Rate limit of the requests of an http virtual server, applied by envoy in the starling agent. It is packed in the
	// `typed_limit` of an entry of the `limit_config` of the virtual server, and only the first such entry is used.
	//
	// Each rate limit of a route (`flock.extensions.route.starling_route.v1.VirtualHostRouteOptions`) builds a descriptor
	// of the request with one entry per action, in order. It is limited by the descriptor declared here with exactly these
	// entries, from a root descriptor down to a descriptor with a policy. A request over the limit of one of its
	// descriptors is answered 429.
	//
	// Each agent counts the requests it receives, so N agents announcing the VIP let through N times the rate.
	// +optional
	Starling *StarlingRateLimit `json:"starling,omitempty"`
}

// Rate limit of the requests of an http virtual server, applied by envoy in the starling agent. It is packed in the
// `typed_limit` of an entry of the `limit_config` of the virtual server, and only the first such entry is used.
//
// Each rate limit of a route (`flock.extensions.route.starling_route.v1.VirtualHostRouteOptions`) builds a descriptor
// of the request with one entry per action, in order. It is limited by the descriptor declared here with exactly these
// entries, from a root descriptor down to a descriptor with a policy. A request over the limit of one of its
// descriptors is answered 429.
//
// Each agent counts the requests it receives, so N agents announcing the VIP let through N times the rate.
type StarlingRateLimit struct {
	// Root descriptors, at least one.
	// +required
	// +listType=atomic
	// +kubebuilder:validation:MinItems=1
	// +kubebuilder:validation:MaxItems=16
	Descriptors []StarlingDescriptor `json:"descriptors,omitempty"`
}

// Descriptor matches one entry of the descriptor of a request, and its sub descriptors match the next entries.
type StarlingDescriptor struct {
	// Key of the entry, the key set by the matching route action (e.g. `remote_address`, or the `descriptor_key` of a
	// request headers action).
	// +required
	// +kubebuilder:validation:MinLength=1
	// +kubebuilder:validation:MaxLength=253
	Key string `json:"key"`

	// Value of the entry. When empty, any value matches and each value gets its own limit, e.g. one limit per client
	// address with the key `remote_address`. A sibling descriptor with the same key and a value replaces it for that
	// value. The agent keeps the counters of at most 10000 such values per virtual server, and a value evicted from them
	// starts again with a full limit.
	// +optional
	// +kubebuilder:validation:MaxLength=253
	Value string `json:"value,omitempty"`

	// Limit of the requests matching the entries from the root descriptor down to this one. A descriptor without policy
	// only groups its sub descriptors.
	// +optional
	Policy *StarlingPolicy `json:"policy,omitempty"`

	// Sub descriptors, matching one more entry.
	// +optional
	// +listType=atomic
	// +kubebuilder:validation:MaxItems=16
	Descriptors []StarlingDescriptorLevel2 `json:"descriptors,omitempty"`

	// When true, the requests over the limit of the policy still reach the backend and only the rate limit stats of envoy
	// count them.
	// +optional
	ShadowMode *bool `json:"shadowMode,omitempty"`
}

// Rate limit policy.
type StarlingPolicy struct {
	// Unit of time for the rate limit, a second when unset.
	// +optional
	Unit TimeUnit `json:"unit,omitempty"`

	// Number of requests allowed within `unit` time.
	// +required
	// +kubebuilder:validation:Minimum=0
	// +kubebuilder:validation:ExclusiveMinimum=true
	RequestsPerUnit int32 `json:"requestsPerUnit"`
}

